waNormalize:
const v = $('WhatsApp Trigger').item.json;
const m = (v.messages || [])[0] || {};
const c = (v.contacts || [])[0] || {};

// The bytes, when the media branch ran. `mediaBase64` is written by `to base64` and by
// NOTHING else, so its presence IS the branch marker -- no isExecuted needed, and no
// second source of truth about which path this item came down.
//
// It is also the DEGRADATION marker. Both Graph calls and the base64 step continue on
// error, so a refused or oversized download arrives here with no bytes and falls through
// to the description below, exactly as an unsupported type does.
const b64 = $input.item.json.mediaBase64 || '';

let kind = 'unsupported';
let text = '';
let token = '';
let location = null;
let media = null;
let form = null;

if (m.type === 'text' && m.text && String(m.text.body || '').trim()) {
  kind = 'text';
  text = String(m.text.body).trim();
} else if (m.type === 'location' && m.location && m.location.latitude != null && m.location.longitude != null) {
  // The location_request_message button, or a pin sent from the attachment menu. Both arrive
  // as the same message type, so the control is a convenience and never a precondition.
  kind = 'location';
  location = { lat: Number(m.location.latitude), lng: Number(m.location.longitude) };
} else if (m.type === 'interactive' && m.interactive && m.interactive.type === 'nfm_reply' && m.interactive.nfm_reply) {
  // A COMPLETED WHATSAPP FORM (a Flow). Not a tap: there is no id to forward. The answer is in
  // `response_json`, which Meta delivers as a STRING CONTAINING JSON -- reading its fields
  // without parsing yields undefined for every one of them, silently.
  //
  // The object goes to jovi-mall's `flow_complete` command UNTOUCHED: its schema is passthrough
  // on purpose, and picking fields here would drop the params of the next form somebody builds.
  // Unparseable travels as null, which the backend refuses and wi-mall-core then REPORTS --
  // never an empty object, which the backend would answer with a silence nobody could see.
  kind = 'form';
  let parsed = null;
  try { parsed = JSON.parse(String(m.interactive.nfm_reply.response_json || '')); } catch (e) { parsed = null; }
  form = (parsed && typeof parsed === 'object' && !Array.isArray(parsed)) ? parsed : null;
} else if (m.type === 'interactive' && m.interactive) {
  const r = m.interactive.button_reply || m.interactive.list_reply || null;
  if (r && r.id) { kind = 'token'; token = String(r.id); }
} else if (m.type === 'button' && m.button && m.button.payload) {
  kind = 'token';
  token = String(m.button.payload);
} else if (b64 && (m.image || m.audio || m.video || m.document)) {
  // Anything wi-mall-perceive can read, already fetched from Meta.
  const a = m.image || m.audio || m.video || m.document;
  // Meta may append parameters (`audio/ogg; codecs=opus`). Perception matches the type
  // exactly, so the parameters have to come off here rather than being refused there.
  // This is what makes a WhatsApp VOICE NOTE land as a clean `audio/ogg`.
  const mime = String(a.mime_type || '').split(';')[0].trim();
  let fname = 'file';
  if (m.image) { fname = 'photo.jpg'; }
  else if (m.audio) { fname = 'voice.ogg'; }
  else if (m.video) { fname = 'video.mp4'; }
  else { fname = String(a.filename || 'file'); }
  kind = 'media';
  media = { fileName: fname, mimeType: mime, contentBase64: b64 };
  // The CAPTION is the customer's own words about the file and travels as ordinary text.
  // A voice note never has one, and that is correct: its transcript becomes the turn.
  text = typeof a.caption === 'string' ? a.caption.trim() : '';
} else {
  // A sticker, or a file Meta would not hand over. Described, never invented as speech.
  text = '[the customer sent something I could not open -- a sticker, or a file too large]';
}

return { json: {
  channel: 'whatsapp',
  // BARE DIGITS, exactly as Meta delivered them. The platform stores E.164 and bridges it
  // server-side; adding a '+' here is the one thing the contract says not to do.
  externalId: String(m.from || c.wa_id || ''),
  messageId: String(m.id || ''),
  kind: kind,
  text: text,
  token: token,
  location: location,
  media: media,
  form: form,
  // WhatsApp satisfies the phone step from the sender id itself, so there is never a
  // contact card to forward on this channel.
  contact: null,
  displayName: (c.profile && c.profile.name) ? String(c.profile.name) : undefined,
  handle: undefined,
  language: undefined,
} };

detectCommand:
// IS THIS MESSAGE A COMMAND? — and deliberately nothing more than that.
//
// ⭐ THE VOCABULARY MOVED SERVER-SIDE ON 2026-09-09, and this node used to hold it: every
// command name, every alias, and the argument grammar. It holds none of them now. The
// reason is the one `bot-surface.md` § 14.6 already gives about parsing a typed answer:
//
//   "A typed answer is language-dependent and whatever reads it is not... That table would
//    have lived in the automation layer, which is the one layer with no copy table."
//
// The alias table IS a five-language table — /chercher /buscar /procurar, /annuler
// /cancelar. Keeping it here meant a vocabulary nobody translates, nobody reviews and
// nobody notices has gone stale. jovi-mall parses now, and answers with a channel-ready
// reply like every other turn.
//
// ⚠ THE RAW TEXT IS WHAT TRAVELS. Never Telegram's bot_command entity: it stops at a
// hyphen, which is why /reset-password could only ever be read as /reset plus trailing
// text — and why the vocabulary is now one word with no separators at all.

const inbound = $('Inbound').first().json;
const sync = $input.first().json;

let kind = '';
let payload = {};

const text = typeof inbound.text === 'string' ? inbound.text.trim() : '';
const onboardingPending = !!(sync && sync.data && sync.data.onboarding && sync.data.onboarding.next);

// A failed /identity/sync is `route turn`'s business — a 4xx body renders its own refusal.
if (sync && sync.success !== false) {
  if (inbound.kind === 'contact' && inbound.contact && !onboardingPending) {
    // ⚠ A CONTACT IS A TAP, NOT TYPED TEXT, so it keeps the webhook command bus rather than
    // going to the parser. It also runs ONLY once onboarding is finished: while the
    // checklist still wants the phone step, `route onboarding` must have the contact — it
    // is the same number, and binding it there is what completes registration. Afterwards a
    // contact can only be answering the request_contact keyboard /login or /password put
    // up, and the PLATFORM's pending intent decides which. n8n never branches on that.
    kind = 'contact';
    payload = {
      contact: {
        phone_number: String(inbound.contact.phoneNumber || ''),
        user_id: inbound.contact.userId,
        first_name: inbound.contact.firstName || undefined,
        last_name: inbound.contact.lastName || undefined
      },
      username: inbound.handle ? String(inbound.handle).replace(/^@/, '') : undefined
    };
  } else if (inbound.kind === 'form') {
    // A COMPLETED WHATSAPP FORM. Like a contact it is not typed text, so it takes the webhook
    // command bus rather than the parser. Unlike a contact it means the same thing at every
    // stage, so it is not gated on onboarding. `flow_complete` reports and never writes, and it
    // decides everything -- including whether there is anything to say. Forwarded untouched.
    kind = 'form';
    payload = inbound.form;
  } else if (inbound.kind === 'text' && text.charAt(0) === '/') {
    // That is the whole test. Which command it is, whether it exists, what its arguments
    // mean and what to say about a typo are all the backend's now.
    kind = 'slash';
  }
}

return [{ json: Object.assign({}, sync, { _kind: kind, _payload: payload }) }];

commandReply:
// The backend words every ordinary outcome AND attaches a channel-ready `reply` to it, so
// the common paths — the credential, every refusal, the request_contact keyboard — arrive
// here already renderable and pass straight through.
//
// This covers the rest: a genuine error envelope carries a sentence but no envelope.
//
// ⚠ It wraps the BACKEND'S sentence and never writes one. That is what keeps "the bot relays,
// never renders" true here — n8n holds no copy table and no button labels, only the two wire
// shapes, and those come from channel-reply.ts on every other path.
const r = $input.first().json || {};
const inbound = $('Inbound').first().json;

// A COMPLETED WHATSAPP FORM IS THE ONE COMMAND WHOSE SILENCE IS AN ANSWER. `flow_complete`
// answers with a reply only when the chat has something to add (a listing form that chose a
// product opens its detail screen). Every other completion is silent on purpose: the form's own
// closing screen already said what happened, and a second message would talk over it. So no
// reply ENDS THE TURN -- never handed to the model, which would greet a customer mid-purchase.
//
// ⚠ Never branch on WHICH form finished. The backend may answer more completions later, and
// that must need no change here.
//
// A refused completion is a platform fault the customer cannot act on -- they have already read
// the closing screen. It FAILS the run so the error workflow reports it (ADR-022); it is never
// swallowed and never worded here.
if (inbound.kind === 'form') {
  if (r.reply) { return [{ json: r }]; }
  if (r.success === false) {
    const e = r.error || {};
    throw new Error('flow_complete refused a WhatsApp form completion: ' + String(e.code || e.message || 'no error body'));
  }
  return [{ json: Object.assign({}, r, { reply: null, endTurn: true }) }];
}

if (r.reply) { return [{ json: r }]; }
const text = (r.error && (r.error.customerMessage || r.error.message)) || '';

// No sentence at all means there is nothing honest to say; `has reply?` sends this to the
// model rather than leaving the customer in silence. On this surface an empty 200 is still
// a TURN — the lesson the address-picker taught on 2026-09-06.
if (!text) { return [{ json: Object.assign({}, r, { reply: null }) }]; }

const reply = inbound.channel === 'telegram'
  ? { channel: 'telegram', method: 'sendMessage', body: { chat_id: inbound.externalId, text: text } }
  : { channel: 'whatsapp', method: 'messages', body: { messaging_product: 'whatsapp', recipient_type: 'individual', to: inbound.externalId, type: 'text', text: { body: text, preview_url: false } } };

return [{ json: Object.assign({}, r, { reply: reply }) }];
